<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class CandidatePhotoController extends Controller{public function store(Request $request):JsonResponse{$this->candidateOnly($request);$request->validate(['photo'=>['required','image','mimes:jpg,jpeg,png,webp','max:3072','dimensions:min_width=200,min_height=200,max_width=4000,max_height=4000']]);$profile=$request->user()->candidateProfile()->firstOrCreate();if($profile->photo_path)Storage::disk('local')->delete($profile->photo_path);$profile->update(['photo_path'=>$request->file('photo')->store('candidates/'.$request->user()->id.'/photos','local')]);return response()->json(['message'=>'Fotografía guardada.','data'=>['has_photo'=>true]]);}public function destroy(Request $request):JsonResponse{$this->candidateOnly($request);$profile=$request->user()->candidateProfile;if($profile?->photo_path)Storage::disk('local')->delete($profile->photo_path);$profile?->update(['photo_path'=>null]);return response()->json(['message'=>'Fotografía eliminada.']);}private function candidateOnly(Request $request):void{abort_unless($request->user()->account_type==='candidate',403,'Esta función es exclusiva para candidatos.');}}
